-- Phase 7 — Row-Level Security.
--
-- Generated by scripts/generate-rls.mjs. Edit the generator, not this file.
--
-- ADR-002 required tenant isolation in the database rather than in the
-- repository layer. This is that. Every policy below denies by default:
-- app_tenant() returns NULL when the connection has not declared a tenant,
-- and NULL never equals anything, so an un-scoped connection reads nothing.

-- The tenant of the current connection. STABLE so the planner may cache it
-- within a statement; the second argument makes a missing setting return
-- NULL instead of raising, which is what turns "forgot to set it" into
-- "sees nothing" rather than "crashes".
CREATE OR REPLACE FUNCTION app_tenant() RETURNS text
  LANGUAGE sql STABLE AS $$ SELECT current_setting('app.tenant_id', true) $$;

REVOKE ALL ON FUNCTION app_tenant() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_tenant() TO kayan_app, kayan_auth, kayan_owner;

