ALTER TABLE "Attachment" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Attachment" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "Attachment";
CREATE POLICY tenant_isolation ON "Attachment" AS PERMISSIVE FOR ALL TO PUBLIC
  USING ((
       EXISTS (SELECT 1 FROM "Customer" c         WHERE c.id = "Attachment"."customerId"   AND c."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "Supplier" s         WHERE s.id = "Attachment"."supplierId"   AND s."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "Quotation" q        WHERE q.id = "Attachment"."quotationId"  AND q."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "SalesOrder" o       WHERE o.id = "Attachment"."salesOrderId" AND o."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "SecondaryExpense" e WHERE e.id = "Attachment"."expenseId"    AND e."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "DamageRecord" d     WHERE d.id = "Attachment"."damageId"     AND d."tenantId" = app_tenant())
  ))
  WITH CHECK ((
       EXISTS (SELECT 1 FROM "Customer" c         WHERE c.id = "Attachment"."customerId"   AND c."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "Supplier" s         WHERE s.id = "Attachment"."supplierId"   AND s."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "Quotation" q        WHERE q.id = "Attachment"."quotationId"  AND q."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "SalesOrder" o       WHERE o.id = "Attachment"."salesOrderId" AND o."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "SecondaryExpense" e WHERE e.id = "Attachment"."expenseId"    AND e."tenantId" = app_tenant())
    OR EXISTS (SELECT 1 FROM "DamageRecord" d     WHERE d.id = "Attachment"."damageId"     AND d."tenantId" = app_tenant())
  ));

-- ── Deliberately global (no RLS) ─────────────────────────
-- Role: the role catalogue is identical for every tenant
-- Permission: the permission catalogue is identical for every tenant
-- RolePermission: the permission matrix is global configuration, seeded from code
-- _prisma_migrations: migration history, owner-only; the app role is never granted it

-- ── Privileges ───────────────────────────────────────────
-- The application role owns nothing and may not create anything. Its
-- entire visibility is decided by the policies above.
GRANT USAGE ON SCHEMA public TO kayan_app, kayan_auth;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO kayan_app, kayan_auth;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO kayan_app, kayan_auth;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO kayan_app, kayan_auth;

-- Migration history is owner business only.
REVOKE ALL ON TABLE "_prisma_migrations" FROM kayan_app, kayan_auth;
